cards.solution:
import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> harga = new ArrayList<>();
        harga.add(12000);
        harga.add(8500);
        harga.add(3000);
        int total = 0;
        for (int h : harga) {
            total += h;
        }
        System.out.println(total);
        System.out.println(Integer.MAX_VALUE);
    }
}

